@startuml

class Traveller {
  + name : string
  + companyName : string
  + address : string
  + billingInformation : string
  + reliabilityRating : float
}

class TravelPreference {
  + description : string
}

class SearchCriteria {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + roomCount : int
  + roomType : string
  + minHotelRating : int
  + maxCostPerNight : float
}

class Booking {
  + bookingIdentifier : string
  + price : float
  + cityArea : string
  + hotelRating : int
  + status : string
  + cancellationDeadline : date
}

class CreditCardInfo {
  + cardNumber : string
}

class SpecialOffer {
  + price : float
  + offerTime : time
}

class Hotel {
  + name : string
  + address : string
  + rating : int
}

class HotelChain {
  + name : string
}

class City {
  + name : string
}

class RoomType {
  + type : string
}

class Availability {
  + isFullyBooked : boolean
}

enum PaymentMethod {
  PRE_PAID
  PAID_AT_HOTEL
}

Traveller "1" -- "*" TravelPreference
Traveller "1" -- "*" Booking
Traveller "1" -- "0..1" CreditCardInfo
Traveller "1" -- "*" SpecialOffer

Booking "1" -- "1" PaymentMethod
Booking "*" -- "0..1" Hotel : confirmed by

Hotel "1" -- "1" City
Hotel "1" -- "0..1" HotelChain
Hotel "1" -- "*" RoomType
Hotel "1" -- "*" Availability

RoomType "1" -- "*" Availability

SearchCriteria "1" -- "*" TravelPreference : filters by

Booking "1" -- "0..1" SpecialOffer : can switch to

@enduml

